#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn dump_and_restore_work_as_in_redis() {
    for mode in MODES {
        replay_steps(STEPS, &[], mode).await;
    }
}

/// A port nothing listens on.
fn closed_port() -> String {
    let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    listener.local_addr().unwrap().port().to_string()
}

async fn cached(c: &mut Client) -> String {
    let info = c.call(&["INFO", "stats"]).await;
    let line = info
        .split("\r\n")
        .find(|l| l.starts_with("migrate_cached_sockets:"));
    line.expect("INFO has it").to_string()
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn migrate_moves_keys_to_another_server() {
    for mode in MODES {
        let (from, _) = start(mode).await;
        // (Its own threads: a MIGRATE waits for it on one of the runtime's.)
        let (to, _) = start(Mode::PerThread).await;
        let port = to.port().to_string();
        let mut a = Client::connect(from).await;
        let mut b = Client::connect(to).await;
        let migrate = |rest: &[&str]| {
            let mut args = vec!["MIGRATE", "127.0.0.1", &port];
            args.extend_from_slice(rest);
            args.into_iter().map(String::from).collect::<Vec<_>>()
        };
        let call = async |c: &mut Client, args: Vec<String>| {
            let args: Vec<&str> = args.iter().map(String::as_str).collect();
            c.call(&args).await
        };
        assert_eq!(a.call(&["SET", "s", "hello"]).await, "+OK\r\n");
        assert_eq!(a.call(&["RPUSH", "l", "x", "1", "y"]).await, ":3\r\n");
        assert_eq!(a.call(&["SET", "t", "v", "PX", "100000"]).await, "+OK\r\n");
        assert_eq!(
            a.call(&["XADD", "x", "1-1", "f", "v"]).await,
            "$3\r\n1-1\r\n"
        );
        assert_eq!(cached(&mut a).await, "migrate_cached_sockets:0");

        // Moved: gone here, there in database 1.
        assert_eq!(call(&mut a, migrate(&["s", "1", "1000"])).await, "+OK\r\n");
        assert_eq!(a.call(&["EXISTS", "s"]).await, ":0\r\n");
        assert_eq!(b.call(&["SELECT", "1"]).await, "+OK\r\n");
        assert_eq!(b.call(&["GET", "s"]).await, "$5\r\nhello\r\n");
        // Copied, several at once, with their TTLs; those not here are left out.
        let keys = migrate(&["", "1", "1000", "COPY", "KEYS", "l", "t", "x", "nosuch"]);
        assert_eq!(call(&mut a, keys).await, "+OK\r\n");
        assert_eq!(a.call(&["EXISTS", "l", "t", "x"]).await, ":3\r\n");
        assert_eq!(
            b.call(&["LRANGE", "l", "0", "-1"]).await,
            "*3\r\n$1\r\nx\r\n$1\r\n1\r\n$1\r\ny\r\n"
        );
        let ttl = b.call(&["PTTL", "t"]).await;
        let ttl: i64 = ttl.trim_start_matches(':').trim_end().parse().unwrap();
        assert!((90_000..=100_000).contains(&ttl), "{ttl}");
        assert_eq!(
            b.call(&["XRANGE", "x", "-", "+"]).await,
            "*1\r\n*2\r\n$3\r\n1-1\r\n*2\r\n$1\r\nf\r\n$1\r\nv\r\n"
        );
        // There already: their error, and nothing goes. REPLACE replaces it.
        assert_eq!(
            call(&mut a, migrate(&["l", "1", "1000"])).await,
            "-ERR Target instance replied with error: BUSYKEY Target key name already exists.\r\n"
        );
        assert_eq!(a.call(&["EXISTS", "l"]).await, ":1\r\n");
        assert_eq!(a.call(&["RPUSH", "l", "z"]).await, ":4\r\n");
        assert_eq!(
            call(&mut a, migrate(&["l", "1", "1000", "REPLACE"])).await,
            "+OK\r\n"
        );
        assert_eq!(b.call(&["LLEN", "l"]).await, ":4\r\n");
        // One connection, kept for the next.
        assert_eq!(cached(&mut a).await, "migrate_cached_sockets:1");
        let clients = b.call(&["CLIENT", "LIST"]).await;
        assert_eq!(
            clients.lines().filter(|l| l.starts_with("id=")).count(),
            2,
            "{clients}"
        );
        // Their AUTH's error is the reply.
        assert_eq!(
            call(&mut a, migrate(&["t", "1", "1000", "AUTH", "pw"])).await,
            "-ERR Target instance replied with error: ERR AUTH <password> called without any \
             password configured for the default user. Are you sure your configuration is correct?\r\n"
        );
        assert_eq!(
            call(&mut a, migrate(&["t", "99", "1000"])).await,
            "-ERR Target instance replied with error: ERR DB index is out of range\r\n"
        );
        // When the kept one is closed, MIGRATE tries again on a new one.
        let own = b.call(&["CLIENT", "ID"]).await;
        let own = format!("id={} ", own.trim_start_matches(':').trim_end());
        let id = clients
            .lines()
            .find(|l| l.starts_with("id=") && !l.starts_with(&own))
            .and_then(|l| l.split(' ').find_map(|f| f.strip_prefix("id=")))
            .expect("the kept connection")
            .to_string();
        assert_eq!(b.call(&["CLIENT", "KILL", "ID", &id]).await, ":1\r\n");
        assert_eq!(call(&mut a, migrate(&["t", "2", "1000"])).await, "+OK\r\n");
        assert_eq!(b.call(&["SELECT", "2"]).await, "+OK\r\n");
        assert_eq!(b.call(&["GET", "t"]).await, "$1\r\nv\r\n");
        // Nothing to send, and nowhere to send it.
        assert_eq!(
            call(&mut a, migrate(&["nosuch", "1", "1000"])).await,
            "+NOKEY\r\n"
        );
        let nowhere = ["MIGRATE", "127.0.0.1", &closed_port(), "x", "0", "1000"];
        assert_eq!(
            a.call(&nowhere).await,
            "-IOERR error or timeout writing to target instance\r\n"
        );
        assert_eq!(a.call(&["EXISTS", "x"]).await, ":1\r\n");
        // (A host that can't be one, so as not to wait for a lookup.)
        let unknown = ["MIGRATE", "no\0host", "1", "x", "0", "1000"];
        assert_eq!(
            a.call(&unknown).await,
            "-IOERR error or timeout connecting to the client\r\n"
        );
    }
}

/// What `DUMP` gives `RESTORE` takes back, for each kind in each of its forms.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn every_value_comes_back() {
    let (addr, _) = start(Mode::PerThread).await;
    let mut c = Client::connect(addr).await;
    let fill = "for i=1,tonumber(ARGV[2]) do redis.call(ARGV[1], KEYS[1], unpack(ARGV[3] == 'z' \
                and {i * 1.5, 'member:' .. i} or ARGV[3] == 'h' and {'field:' .. i, 'value:' .. i} \
                or ARGV[3] == 'i' and {i} or {'element:' .. i})) end return 1";
    let setup: &[&[&str]] = &[
        &["SET", "s", "hello"],
        &["SET", "n", "-12345"],
        &["SET", "long", &"abc".repeat(100)],
        &["RPUSH", "l", "a", "1", "b"],
        &["EVAL", fill, "1", "lbig", "rpush", "5000", "l"],
        &["SADD", "si", "1", "2", "3"],
        &["SADD", "ss", "a", "b"],
        &["EVAL", fill, "1", "sbig", "sadd", "300", "m"],
        &["EVAL", fill, "1", "sibig", "sadd", "600", "i"],
        &["ZADD", "z", "1", "a", "2.5", "b"],
        &["EVAL", fill, "1", "zbig", "zadd", "300", "z"],
        &["HSET", "h", "f", "v"],
        &["EVAL", fill, "1", "hbig", "hset", "300", "h"],
        &["XADD", "x", "1-1", "a", "1"],
        &["XGROUP", "CREATE", "x", "g", "0"],
        &["XREADGROUP", "GROUP", "g", "c", "STREAMS", "x", ">"],
    ];
    for args in setup {
        assert!(!c.call(args).await.starts_with('-'), "{args:?}");
    }
    for key in [
        "s", "n", "long", "l", "lbig", "si", "ss", "sbig", "sibig", "z", "zbig", "h", "hbig", "x",
    ] {
        let req = |args: &[&[u8]]| common::req(args);
        c.send_raw(&req(&[b"DUMP", key.as_bytes()])).await;
        let reply = c.raw_reply().await;
        let common::Value::Bulk(payload) = common::parse(&reply) else {
            panic!("{key}: {reply:?}");
        };
        let copy = format!("{key}:copy");
        c.send_raw(&req(&[b"RESTORE", copy.as_bytes(), b"0", &payload]))
            .await;
        assert_eq!(c.raw_reply().await, b"+OK\r\n", "{key}");
        // The same, as its DUMP and its encoding say (but for hash tables, whose
        // order can change: their members, then).
        if ["sbig", "sibig", "hbig"].contains(&key) {
            let all = if key == "hbig" { "HGETALL" } else { "SMEMBERS" };
            let sorted = |reply: Vec<u8>| {
                let mut items = common::parse(&reply).bulks();
                items.sort();
                items
            };
            c.send_raw(&req(&[all.as_bytes(), key.as_bytes()])).await;
            let original = sorted(c.raw_reply().await);
            c.send_raw(&req(&[all.as_bytes(), copy.as_bytes()])).await;
            assert_eq!(sorted(c.raw_reply().await), original, "{key}");
        } else {
            c.send_raw(&req(&[b"DUMP", copy.as_bytes()])).await;
            assert_eq!(c.raw_reply().await, reply, "{key}");
        }
        let encoding = c.call(&["OBJECT", "ENCODING", key]).await;
        assert_eq!(
            c.call(&["OBJECT", "ENCODING", &copy]).await,
            encoding,
            "{key}"
        );
    }
    assert_eq!(
        c.call(&["XINFO", "GROUPS", "x:copy"]).await,
        c.call(&["XINFO", "GROUPS", "x"]).await
    );
    assert_eq!(
        c.call(&["ZRANGE", "zbig:copy", "0", "-1", "WITHSCORES"])
            .await,
        c.call(&["ZRANGE", "zbig", "0", "-1", "WITHSCORES"]).await
    );
}
